const CACHE='tc-stems-shell-guitar-v12';const FILES=["./install.js","./repertoire.js","./guitar-model.js","./mix-engine.js","./logo.png","./icon-192.png","./icon-512.png","./icon-180.png","./mp3-worker.js","./vendor/lame/lame.min.js","./separator-worker.js", "./style.css", "./app.js", "./manifest.webmanifest", "./index.html", "./icon.svg", "./audio-utils.js", "./vendor/ort/ort-wasm-simd-threaded.mjs", "./vendor/ort/ort-wasm-simd-threaded.wasm", "./vendor/ort/ort.wasm.min.mjs", "./vendor/demucs/src/fft.js", "./vendor/demucs/src/constants.js", "./vendor/demucs/src/processor.js", "./vendor/demucs/src/index.js"];self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES)).then(()=>self.skipWaiting())));self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(key=>key.startsWith('tc-stems-shell-')&&key!==CACHE).map(key=>caches.delete(key)))).then(()=>self.clients.claim())));self.addEventListener('fetch',event=>{if(new URL(event.request.url).pathname.startsWith('/api/'))return;if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).catch(async()=>{const cached=await caches.match(event.request);if(cached)return cached;if(event.request.mode==='navigate')return caches.match('./index.html');return Response.error()}))});